"use client";

import React, { useState, useMemo } from "react";
import manifestData from "@/utils/dictionaries.json";

interface KaynaklarProps {
  onClose?: () => void;
}

/** İnce, tekrar eden baklava-dizi süslemesi — Çerkes gümüş işlemeciliğinden
 * ödünç alınmış bir motif. Sayfada yalnızca iki yerde (başlık altı / dipnot
 * üstü) kullanılır; abartılmaz. */
function SusBandi({ className = "" }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 400 12"
      preserveAspectRatio="none"
      className={`w-full h-3 ${className}`}
      aria-hidden="true"
    >
      <line x1="0" y1="6" x2="400" y2="6" stroke="currentColor" strokeWidth="0.75" opacity="0.35" />
      {Array.from({ length: 20 }).map((_, i) => {
        const x = 10 + i * 20;
        return (
          <path
            key={i}
            d={`M ${x - 4} 6 L ${x} 1.5 L ${x + 4} 6 L ${x} 10.5 Z`}
            fill={i % 2 === 0 ? "currentColor" : "none"}
            stroke="currentColor"
            strokeWidth="0.75"
            opacity={i % 2 === 0 ? 0.9 : 0.35}
          />
        );
      })}
    </svg>
  );
}

export default function Kaynaklar({ onClose }: KaynaklarProps) {
  const [aramaMetni, setAramaMetni] = useState("");
  const [seciliDiyalekt, setSeciliDiyalekt] = useState<"HEPSİ" | "BATI" | "DOĞU">("HEPSİ");

  // İstatistik Hesaplamaları
  const istatistikler = useMemo(() => {
    const toplamSozluk = manifestData.length;
    let toplamKayit = 0;
    let batiCount = 0;
    let doguCount = 0;
    const hedefDiller = new Set<string>();

    manifestData.forEach((s: any) => {
      toplamKayit += Number(s.count || s.total_words || s.kayitSayisi || 0);

      const dialect = (s.dialect || s.lehce || "").toUpperCase();
      if (dialect.includes("BATI") || dialect.includes("ADY")) batiCount++;
      if (dialect.includes("DOGU") || dialect.includes("KBD")) doguCount++;

      const lang = (s.targetLanguage || s.language || s.dil || "").toLowerCase();
      if (lang) hedefDiller.add(lang);
    });

    return {
      toplamSozluk,
      toplamKayit,
      batiCount,
      doguCount,
      hedefDilSayisi: hedefDiller.size || 4,
    };
  }, []);

  // Filtrelenmiş Manifest Verisi
  const filtrelenmisManifest = useMemo(() => {
    return manifestData.filter((sozluk: any) => {
      const baslik = (sozluk.title || sozluk.ad || sozluk.file || "").toLowerCase();
      const yazar = (sozluk.author || sozluk.yazar || "").toLowerCase();
      const sehir = (sozluk.publisher || sozluk.city || sozluk.yayinEvi || "").toLowerCase();
      const idStr = (sozluk.id || "").toString();
      const dialect = (sozluk.dialect || sozluk.lehce || "").toUpperCase();

      const aramaUyum =
        baslik.includes(aramaMetni.toLowerCase()) ||
        yazar.includes(aramaMetni.toLowerCase()) ||
        sehir.includes(aramaMetni.toLowerCase()) ||
        idStr.includes(aramaMetni);

      let diyalektUyum = true;
      if (seciliDiyalekt === "BATI") diyalektUyum = dialect.includes("BATI") || dialect.includes("ADY");
      if (seciliDiyalekt === "DOĞU") diyalektUyum = dialect.includes("DOGU") || dialect.includes("KBD");

      return aramaUyum && diyalektUyum;
    });
  }, [aramaMetni, seciliDiyalekt]);

  return (
    <div className="min-h-screen bg-[#F4EFE1] dark:bg-[#161C16] text-[#1E2A22] dark:text-[#EDE7D6] font-body">
      <style jsx global>{`
        @import url("https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,600;0,9..144,700;1,9..144,500&family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap");
        .font-display {
          font-family: "Fraunces", ui-serif, Georgia, serif;
        }
        .font-body {
          font-family: "IBM Plex Sans", ui-sans-serif, system-ui, sans-serif;
        }
        .font-mono-plex {
          font-family: "IBM Plex Mono", ui-monospace, monospace;
        }
      `}</style>

      <div className="max-w-5xl mx-auto px-5 sm:px-8 py-10">
        {/* Kapat Butonu */}
        {onClose && (
          <button
            onClick={onClose}
            aria-label="Kaynaklar sayfasını kapat ve sözlüğe dön"
            className="group mb-10 inline-flex items-center gap-2 text-[11px] font-mono-plex font-medium tracking-wide uppercase text-[#5B6B57] dark:text-[#9AAE93] hover:text-[#1F4D3A] dark:hover:text-[#C7B36A] transition-colors"
          >
            <span className="transition-transform duration-300 group-hover:-translate-x-1">←</span>
            <span className="border-b border-transparent group-hover:border-current pb-0.5">Sözlüğe dön</span>
          </button>
        )}

        {/* Başlık Plaketi */}
        <header className="mb-6">
          <div className="text-[11px] font-mono-plex font-semibold tracking-[0.2em] uppercase text-[#9C6B2E] dark:text-[#C7B36A] mb-3">
            Dijital Korpus — Bibliyografya Fişi
          </div>
          <h1 className="font-display italic font-medium text-4xl md:text-5xl leading-[1.05] text-[#1F4D3A] dark:text-[#EDE7D6] mb-4">
            Kaynak Sözlükler
            <br />
            <span className="not-italic font-semibold text-[#1E2A22] dark:text-[#EDE7D6]">Katalog Künyesi</span>
          </h1>
          <p className="text-[#5B6B57] dark:text-[#9AAE93] text-sm md:text-[15px] max-w-2xl leading-relaxed font-body">
            Platformda indekslenen sözlüklerin özgün yayın künyeleri, yazar ve edisyon bilgileri
            ile diyalektik dağılımları — her eser, tek bir kart olarak fişlenmiştir.
          </p>
        </header>

        <SusBandi className="text-[#9C6B2E] dark:text-[#C7B36A] mb-10" />

        {/* İstatistik Plaketi */}
        <div className="grid grid-cols-2 md:grid-cols-4 divide-x divide-[#D9CCA6] dark:divide-[#2C3A2A] mb-12 border-y border-[#D9CCA6] dark:border-[#2C3A2A]">
          <div className="px-4 py-5 first:pl-0">
            <div className="font-display font-semibold text-3xl text-[#1F4D3A] dark:text-[#EDE7D6] tabular-nums">
              {istatistikler.toplamSozluk}
            </div>
            <div className="text-[10.5px] font-mono-plex font-medium text-[#8A7A52] dark:text-[#9AAE93] mt-1 uppercase tracking-wider">
              Kataloglu Eser
            </div>
          </div>

          <div className="px-4 py-5">
            <div className="font-display font-semibold text-3xl text-[#9C4A32] dark:text-[#D4795E] tabular-nums">
              {istatistikler.toplamKayit.toLocaleString("tr-TR")}
            </div>
            <div className="text-[10.5px] font-mono-plex font-medium text-[#8A7A52] dark:text-[#9AAE93] mt-1 uppercase tracking-wider">
              Dijitalize Madde
            </div>
          </div>

          <div className="px-4 py-5">
            <div className="font-display font-semibold text-2xl text-[#1E2A22] dark:text-[#EDE7D6] tabular-nums">
              <span className="text-[#1F4D3A] dark:text-[#7FA88C]">{istatistikler.batiCount}</span>
              <span className="mx-1.5 text-[#D9CCA6] dark:text-[#2C3A2A] font-body">/</span>
              <span className="text-[#9C4A32] dark:text-[#D4795E]">{istatistikler.doguCount}</span>
            </div>
            <div className="text-[10.5px] font-mono-plex font-medium text-[#8A7A52] dark:text-[#9AAE93] mt-1 uppercase tracking-wider">
              Batı / Doğu Diyalekti
            </div>
          </div>

          <div className="px-4 py-5 last:pr-0">
            <div className="font-display font-semibold text-3xl text-[#9C6B2E] dark:text-[#C7B36A] tabular-nums">
              {istatistikler.hedefDilSayisi}
            </div>
            <div className="text-[10.5px] font-mono-plex font-medium text-[#8A7A52] dark:text-[#9AAE93] mt-1 uppercase tracking-wider">
              Hedef Dil Çifti
            </div>
          </div>
        </div>

        {/* Arama & Filtreleme */}
        <section className="mb-10 flex flex-col sm:flex-row items-stretch sm:items-end justify-between gap-5">
          <div className="w-full sm:w-72">
            <label className="block text-[10.5px] font-mono-plex font-semibold uppercase tracking-wider text-[#8A7A52] dark:text-[#9AAE93] mb-1.5">
              Fişlerde Ara
            </label>
            <input
              type="text"
              placeholder="Eser adı, yazar veya ID (ör: 18)"
              value={aramaMetni}
              onChange={(e) => setAramaMetni(e.target.value)}
              className="w-full px-0 py-2 bg-transparent border-0 border-b-2 border-[#D9CCA6] dark:border-[#2C3A2A] text-sm font-body placeholder:text-[#B3A57C] dark:placeholder:text-[#5B6B57] focus:outline-none focus:border-[#1F4D3A] dark:focus:border-[#C7B36A] transition-colors"
            />
          </div>

          <div className="flex items-center gap-5 text-xs font-mono-plex font-semibold uppercase tracking-wide">
            {(["HEPSİ", "BATI", "DOĞU"] as const).map((d) => (
              <button
                key={d}
                onClick={() => setSeciliDiyalekt(d)}
                className={`pb-1 border-b-2 transition-colors ${
                  seciliDiyalekt === d
                    ? "border-[#1F4D3A] dark:border-[#C7B36A] text-[#1F4D3A] dark:text-[#C7B36A]"
                    : "border-transparent text-[#9C917A] dark:text-[#6B7A66] hover:text-[#5B6B57] dark:hover:text-[#9AAE93]"
                }`}
              >
                {d === "HEPSİ" ? "Tüm Korpus" : d === "BATI" ? "Batı · Adıgece" : "Doğu · Kabardeyce"}
              </button>
            ))}
          </div>
        </section>

        {/* Bibliyografik Fiş Kataloğu */}
        <section className="mb-16">
          <div className="grid gap-6 md:grid-cols-2">
            {filtrelenmisManifest.map((sozluk: any, idx: number) => {
              const yazar = sozluk.author || sozluk.yazar || "Belirtilmemiş";
              const baslik = sozluk.title || sozluk.ad || sozluk.file;
              const yil = sozluk.year || sozluk.yil;
              const sehirYayin = sozluk.publisher || sozluk.city || sozluk.yayinEvi;
              const kayitSayisi = sozluk.count || sozluk.total_words || sozluk.kayitSayisi;
              const lehce = (sozluk.dialect || sozluk.lehce || "GENEL").toUpperCase();
              const dilCifti = sozluk.langPair || sozluk.dilCifti || `${lehce} → HEDEF`;
              const sozlukId = sozluk.id !== undefined ? sozluk.id : idx + 1;
              const batiMi = lehce.includes("BATI") || lehce.includes("ADY");
              const doguMu = lehce.includes("DOGU") || lehce.includes("KBD");
              const kenarRengi = batiMi
                ? "border-l-[#1F4D3A] dark:border-l-[#7FA88C]"
                : doguMu
                ? "border-l-[#9C4A32] dark:border-l-[#D4795E]"
                : "border-l-[#9C6B2E] dark:border-l-[#C7B36A]";

              return (
                <article
                  key={sozluk.file || idx}
                  className={`relative pl-6 pr-5 py-5 border-l-4 ${kenarRengi} bg-[#FBF8EF] dark:bg-[#1C231C] shadow-[2px_2px_0_0_#D9CCA6] dark:shadow-[2px_2px_0_0_#2C3A2A] hover:shadow-[3px_3px_0_0_#D9CCA6] dark:hover:shadow-[3px_3px_0_0_#2C3A2A] hover:-translate-y-[1px] transition-all duration-200 flex flex-col justify-between`}
                >
                  {/* iki delik — kart-katalog izi */}
                  <div className="absolute -left-[7px] top-5 w-[9px] h-[9px] rounded-full bg-[#F4EFE1] dark:bg-[#161C16] border border-[#D9CCA6] dark:border-[#2C3A2A]" />
                  <div className="absolute -left-[7px] bottom-5 w-[9px] h-[9px] rounded-full bg-[#F4EFE1] dark:bg-[#161C16] border border-[#D9CCA6] dark:border-[#2C3A2A]" />

                  <div>
                    <div className="flex items-start justify-between gap-3 mb-2.5">
                      <span className="font-mono-plex text-[10.5px] font-semibold text-[#8A7A52] dark:text-[#9AAE93] tracking-wide">
                        FİŞ № {sozlukId}
                      </span>
                      <span className="text-[10.5px] font-mono-plex font-medium text-[#8A7A52] dark:text-[#9AAE93] whitespace-nowrap">
                        {dilCifti}
                      </span>
                    </div>

                    <h3 className="font-display font-semibold text-[19px] leading-snug text-[#1E2A22] dark:text-[#EDE7D6]">
                      {baslik}
                    </h3>

                    <div className="mt-2.5 text-[13px] text-[#4A5647] dark:text-[#C4CFBE] font-body">
                      <span className="text-[#8A7A52] dark:text-[#9AAE93]">Yazar / Hazırlayan — </span>
                      <span className="font-medium">{yazar}</span>
                    </div>

                    {(yil || sehirYayin) && (
                      <div className="mt-1 flex flex-wrap gap-x-4 text-[12px] text-[#8A7A52] dark:text-[#9AAE93] font-mono-plex">
                        {yil && <span>{yil}</span>}
                        {sehirYayin && <span>{sehirYayin}</span>}
                      </div>
                    )}
                  </div>

                  <div className="mt-4 pt-3 border-t border-dashed border-[#D9CCA6] dark:border-[#2C3A2A] flex items-center justify-between text-[11px] font-mono-plex text-[#9C917A] dark:text-[#6B7A66]">
                    <span className="truncate max-w-[190px]" title={sozluk.file}>
                      {sozluk.file}
                    </span>
                    {kayitSayisi && (
                      <span className="font-semibold text-[#1F4D3A] dark:text-[#C7B36A]">
                        {Number(kayitSayisi).toLocaleString("tr-TR")} madde
                      </span>
                    )}
                  </div>
                </article>
              );
            })}
          </div>

          {filtrelenmisManifest.length === 0 && (
            <p className="text-center text-sm text-[#8A7A52] dark:text-[#9AAE93] font-body py-16">
              Aramanızla eşleşen bir fiş bulunamadı.
            </p>
          )}
        </section>

        <SusBandi className="text-[#9C6B2E] dark:text-[#C7B36A] mb-6" />

        <footer className="text-center text-[11px] font-mono-plex uppercase tracking-wider text-[#9C917A] dark:text-[#6B7A66] pb-4">
          Çerkesçe Sözlük Platformu — Dijital Korpus Bibliyografyası
        </footer>
      </div>
    </div>
  );
}